-- Reviewed additive operational migration; no operational attempt is rewritten during installation.
lock table public.exam_attempts in share row exclusive mode;
do $$begin if exists(select 1 from public.exam_attempts where organization_id='6e143c55-7be5-4e6e-9f1a-8f8db429956a') then raise exception 'Preflight changed: review operational attempts and backup before installation';end if;end$$;
create table public.exam_sessions(id uuid primary key default gen_random_uuid(),organization_id uuid not null,exam_id uuid not null,name text not null check(length(trim(name)) between 1 and 100),starts_at timestamptz not null,ends_at timestamptz not null,foreign key(organization_id,exam_id) references public.exams(organization_id,id),unique(organization_id,exam_id,id),unique(exam_id,name),check(ends_at>starts_at));
alter table public.exam_sessions enable row level security;
revoke all on public.exam_sessions from public,anon,authenticated;
alter table public.supervisor_assignments add column session_id uuid,add foreign key(organization_id,exam_id,session_id) references public.exam_sessions(organization_id,exam_id,id);
create unique index assignment_session_unique on public.supervisor_assignments(room_id,coalesce(session_id,'00000000-0000-0000-0000-000000000000'::uuid)) where active;
create table private.operational_requests(actor_id uuid not null,request_id uuid not null,input jsonb not null,result jsonb not null,primary key(actor_id,request_id));
create table private.attempt_overrides(id uuid primary key default gen_random_uuid(),attempt_id uuid not null references public.exam_attempts(id),actor_id uuid not null,action text not null,reason text not null,before_state jsonb not null,created_at timestamptz not null default now());
create table private.notifications(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),sender_id uuid not null references public.profiles(id),message text not null check(length(trim(message)) between 1 and 2000),created_at timestamptz not null default now());
create table private.notification_receipts(notification_id uuid not null references private.notifications(id),recipient_id uuid not null references public.profiles(id),read_at timestamptz,primary key(notification_id,recipient_id));
create index receipts_recipient on private.notification_receipts(recipient_id,notification_id);
do $$declare t text;begin foreach t in array array['operational_requests','attempt_overrides','notifications','notification_receipts'] loop execute format('alter table private.%I enable row level security',t);execute format('revoke all on private.%I from public,anon,authenticated',t);end loop;end$$;
create function private.effective_supervisor(target uuid) returns uuid language sql stable security definer set search_path='' as $$select coalesce((select s.substitute_supervisor_id from public.supervisor_substitutions s join public.profiles p on p.id=s.substitute_supervisor_id and p.active and p.role in ('teacher','supervisor') where s.assignment_id=a.id and s.revoked_at is null and s.effective_from<=now() and (s.effective_until is null or s.effective_until>now()) limit 1),a.original_supervisor_id) from public.supervisor_assignments a join public.profiles p on p.id=a.original_supervisor_id and p.active and p.role in ('teacher','supervisor') where a.id=target and a.active and (a.session_id is null or exists(select 1 from public.exam_sessions es where es.id=a.session_id and es.starts_at<=now() and es.ends_at>now()))$$;
create or replace function private.supervisor_allowed() returns boolean language sql stable security definer set search_path='' as $$select private.actor_org() is not null and exists(select 1 from public.supervisor_assignments a where a.organization_id=private.actor_org() and private.effective_supervisor(a.id)=auth.uid())$$;
create function private.ops_student(eid uuid,sid uuid,writing boolean default false) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.exams e join public.profiles p on p.id=sid and p.organization_id=e.organization_id and p.role='student' and p.active where e.id=eid and e.organization_id=private.actor_org() and exists(select 1 from public.exam_classes ec join public.student_enrollments en on en.class_id=ec.class_id and en.active where ec.exam_id=e.id and en.student_id=sid) and (private.is_admin() or exists(select 1 from public.exam_room_students rs join public.supervisor_assignments a on a.exam_id=rs.exam_id and a.room_id=rs.room_id where rs.exam_id=eid and rs.student_id=sid and private.effective_supervisor(a.id)=auth.uid()) or (not writing and exists(select 1 from public.teacher_assignments t join public.student_enrollments en on en.class_id=t.class_id and en.active join public.exam_classes ec on ec.class_id=t.class_id and ec.exam_id=e.id where t.teacher_id=auth.uid() and t.active and t.organization_id=e.organization_id and t.subject_id=e.subject_id and en.student_id=sid))))$$;
create or replace function private.can_review_attempt(target uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.exam_attempts a where a.id=target and a.organization_id=private.actor_org() and (private.is_admin() or private.ops_student(a.exam_id,a.student_id,true)))$$;
create or replace function private.room_capacity() returns trigger language plpgsql security definer set search_path='' as $$declare cap int;begin
 select capacity into cap from public.exam_rooms where id=new.room_id and exam_id=new.exam_id and organization_id=new.organization_id for update;if not found then raise exception 'Ruang tidak tersedia';end if;
 if not exists(select 1 from public.profiles p join public.student_enrollments en on en.student_id=p.id and en.active join public.exam_classes ec on ec.class_id=en.class_id and ec.exam_id=new.exam_id where p.id=new.student_id and p.organization_id=new.organization_id and p.active and p.role='student') then raise exception 'Peserta tidak eligible';end if;
 if cap>0 and (select count(*) from public.exam_room_students where room_id=new.room_id and student_id<>new.student_id)>=cap then raise exception 'Kapasitas ruang terlampaui';end if;return new;end$$;
drop trigger check_room_capacity on public.exam_room_students;
create trigger check_room_capacity before insert or update on public.exam_room_students for each row execute function private.room_capacity();
create function private.reset_attempt_insert() returns trigger language plpgsql security definer set search_path='' as $$declare old public.exam_attempts;begin
 select * into old from public.exam_attempts where exam_id=new.exam_id and student_id=new.student_id order by attempt_number desc limit 1;
 if found then new.attempt_number:=old.attempt_number+1;if old.status='reset' then new.deadline_at:=least(new.deadline_at,old.deadline_at);if new.deadline_at<=clock_timestamp() then raise exception 'Deadline tetap telah lewat; reset tidak menambah waktu';end if;end if;end if;return new;end$$;
create trigger reset_attempt_sequence before insert on public.exam_attempts for each row execute function private.reset_attempt_insert();
create function private.ops_command(input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare op text:=input->>'action';org uuid:=private.actor_org();target uuid:=nullif(input->>'id','')::uuid;eid uuid:=nullif(input->>'exam_id','')::uuid;sid uuid;room public.exam_rooms;ex public.exams;a public.exam_attempts;ass public.supervisor_assignments;req uuid;prev private.operational_requests;result jsonb;item jsonb;ids uuid[];uid uuid:=auth.uid();nid uuid;n int;begin
 if org is null then raise exception 'AUTH: Sesi tidak valid';end if;
 if op='inbox' then select coalesce(jsonb_agg(v order by v->>'created_at' desc),'[]') into result from(select jsonb_build_object('id',m.id,'message',m.message,'created_at',m.created_at,'read_at',r.read_at) v from private.notification_receipts r join private.notifications m on m.id=r.notification_id where r.recipient_id=uid and m.organization_id=org order by m.created_at desc limit 100)x;return result;end if;
 if op='read' then update private.notification_receipts r set read_at=coalesce(read_at,clock_timestamp()) where r.notification_id=target and r.recipient_id=uid;return jsonb_build_object('saved',found);end if;
 if not exists(select 1 from public.profiles where id=uid and active and role in ('admin','teacher','supervisor')) then raise exception 'AUTH: Akses petugas diperlukan';end if;
 if op='options' then return jsonb_build_object('admin',private.is_admin(),'organization_id',org,'exams',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'title',e.title)) from public.exams e where e.organization_id=org and (private.is_admin() or exists(select 1 from public.profiles p where private.ops_student(e.id,p.id,false)))),'[]'),'staff',case when private.is_admin() then coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.full_name,'role',p.role)) from public.profiles p where p.organization_id=org and p.active and p.role in ('teacher','supervisor')),'[]') else '[]'::jsonb end);end if;
 if op='rooms' then
 if not private.is_admin() then raise exception 'AUTH: Hanya Admin mengelola ruang';end if;
 return jsonb_build_object('rooms',coalesce((select jsonb_agg(to_jsonb(r)||jsonb_build_object('count',(select count(*) from public.exam_room_students rs where rs.room_id=r.id))) from public.exam_rooms r where r.organization_id=org and r.exam_id=eid),'[]'),'sessions',coalesce((select jsonb_agg(to_jsonb(s)) from public.exam_sessions s where s.organization_id=org and s.exam_id=eid),'[]'),'roster',coalesce((select jsonb_agg(to_jsonb(rs)||jsonb_build_object('name',p.full_name)) from public.exam_room_students rs join public.profiles p on p.id=rs.student_id where rs.organization_id=org and rs.exam_id=eid),'[]'),'eligible',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.full_name)) from public.profiles p where private.ops_student(eid,p.id,false)),'[]'),'assignments',coalesce((select jsonb_agg(to_jsonb(s)||jsonb_build_object('effective_supervisor',private.effective_supervisor(s.id),'substitutions',coalesce((select jsonb_agg(to_jsonb(ss)) from public.supervisor_substitutions ss where ss.assignment_id=s.id),'[]'))) from public.supervisor_assignments s where s.organization_id=org and s.exam_id=eid),'[]'));end if;
 if op='monitor' then
 -- Deadline transition occurs inside the same transaction before producing a committed status.
 for a in select ea.* from public.exam_attempts ea join public.exams e on e.id=ea.exam_id where ea.exam_id=eid and ea.finalized_at is null and ea.status='in_progress' and (ea.deadline_at<=clock_timestamp() or e.status in ('closed','archived')) and private.ops_student(eid,ea.student_id,false) order by ea.id for update of ea loop perform private.attempt_finalize(a.id,'timeout');end loop;
 select coalesce(jsonb_agg(v order by v->>'student'),'[]') into result from (select jsonb_build_object('student_id',p.id,'student',p.full_name,'username',p.username,'attempt_id',ea.id,'version',ea.version,'status',coalesce(ea.status,'not_started'),'logged_in',exists(select 1 from auth.sessions s where s.user_id=p.id and (s.not_after is null or s.not_after>now())),'deadline_at',ea.deadline_at,'started_at',ea.started_at,'finalized_at',ea.finalized_at,'answers',(select count(*) from public.attempt_answers aa where aa.attempt_id=ea.id),'events',(select count(*) from private.integrity_events ie where ie.attempt_id=ea.id),'countable_events',(select count(*) from private.integrity_events ie where ie.attempt_id=ea.id and ie.countable),'room_id',rs.room_id,'room',r.name,'can_act',private.ops_student(eid,p.id,true),'score',ea.score_percent,'pending',ea.grading_pending) v from public.profiles p left join lateral(select * from public.exam_attempts aa where aa.exam_id=eid and aa.student_id=p.id and aa.status<>'reset' order by aa.attempt_number desc limit 1)ea on true left join public.exam_room_students rs on rs.exam_id=eid and rs.student_id=p.id left join public.exam_rooms r on r.id=rs.room_id where private.ops_student(eid,p.id,false) and (nullif(input->>'room_id','') is null or rs.room_id=(input->>'room_id')::uuid) and (coalesce(input->>'search','')='' or p.full_name ilike '%'||(input->>'search')||'%' or p.username ilike '%'||(input->>'search')||'%'))x;return result;end if;
 if op='sent' then select coalesce(jsonb_agg(v order by v->>'created_at' desc),'[]') into result from(select jsonb_build_object('id',m.id,'message',m.message,'created_at',m.created_at,'receipts',(select jsonb_agg(jsonb_build_object('student',p.full_name,'read_at',r.read_at)) from private.notification_receipts r join public.profiles p on p.id=r.recipient_id where r.notification_id=m.id and (private.is_admin() or exists(select 1 from public.exams e where private.ops_student(e.id,p.id,false))))) v from private.notifications m where m.organization_id=org and (m.sender_id=uid or private.is_admin()) order by m.created_at desc limit 50)x;return result;end if;
 if op='history' then if not private.can_review_attempt(target) then raise exception 'AUTH: Di luar cakupan';end if;return jsonb_build_object('events',private.review_attempt(jsonb_build_object('action','events','attempt_id',target)),'overrides',coalesce((select jsonb_agg(to_jsonb(o)-'before_state' order by created_at desc) from private.attempt_overrides o where o.attempt_id=target),'[]'));end if;
 if op='cards' then
 if jsonb_array_length(input->'student_ids') not between 1 and 500 then raise exception 'Pilih 1–500 peserta';end if;
 if exists(select 1 from jsonb_array_elements_text(input->'student_ids') x where not private.ops_student(eid,x::uuid,false)) then raise exception 'AUTH: Kartu di luar cakupan';end if;
 return jsonb_build_object('exam',(select jsonb_build_object('id',id,'title',title,'starts_at',starts_at,'ends_at',ends_at) from public.exams where id=eid),'students',(select jsonb_agg(jsonb_build_object('id',p.id,'name',p.full_name,'username',p.username,'room',r.name)) from public.profiles p left join public.exam_room_students rs on rs.exam_id=eid and rs.student_id=p.id left join public.exam_rooms r on r.id=rs.room_id where p.id in(select value::uuid from jsonb_array_elements_text(input->'student_ids'))),'settings',coalesce((select to_jsonb(s)-'organization_id' from private.report_settings s where s.organization_id=org),jsonb_build_object('school',(select name from public.organizations where id=org),'address','','official','','official_title','','logo_media_id',null)));end if;
 req:=(input->>'request_id')::uuid;if req is null then raise exception 'Request ID wajib';end if;
 if op in ('room_save','room_delete','session_save','session_delete','roster_add','roster_remove','assign','unassign','substitute','revoke') and not private.is_admin() then raise exception 'AUTH: Hanya Admin mengelola penugasan';end if;
 if op in ('reset','unlock','disqualify') then
 if jsonb_array_length(input->'attempts') not between 1 and 100 or length(trim(coalesce(input->>'reason',''))) not between 5 and 1000 or input->>'confirmation'<>'KONFIRMASI' then raise exception '1–100 attempt, alasan dan konfirmasi wajib';end if;
 for item in select value from jsonb_array_elements(input->'attempts') loop if not private.can_review_attempt((item->>'id')::uuid) then raise exception 'AUTH: Tindakan di luar cakupan';end if;end loop;
 end if;
 if op='broadcast' and exists(select 1 from jsonb_array_elements_text(coalesce(input->'student_ids','[]')) x where not private.ops_student(eid,x::uuid,false)) then raise exception 'AUTH: Penerima di luar cakupan';end if;
 select * into prev from private.operational_requests where actor_id=uid and request_id=req;if found then if prev.input<>input then raise exception 'IDEMPOTENCY_CONFLICT';end if;return prev.result;end if;
 if op in ('room_save','session_save','roster_add','roster_remove','assign') then select * into ex from public.exams where id=eid and organization_id=org for update;if not found then raise exception 'AUTH: Ujian tidak tersedia';end if;end if;
 if op='room_save' then
 if length(trim(coalesce(input->>'name',''))) not between 1 and 100 or (input->>'capacity')::int<0 then raise exception 'Nama/kapasitas tidak valid';end if;
 if target is null then insert into public.exam_rooms(organization_id,exam_id,name,capacity) values(org,eid,trim(input->>'name'),(input->>'capacity')::int) returning id into target;else
 select * into room from public.exam_rooms where id=target and exam_id=eid and organization_id=org for update;if not found then raise exception 'Ruang tidak tersedia';end if;
 if (input->>'capacity')::int>0 and (select count(*) from public.exam_room_students where room_id=target)>(input->>'capacity')::int then raise exception 'Kapasitas di bawah roster';end if;
 update public.exam_rooms set name=trim(input->>'name'),capacity=(input->>'capacity')::int where id=target;end if;result:=jsonb_build_object('id',target);
 elsif op='room_delete' then
 if exists(select 1 from public.exam_room_students where room_id=target) or exists(select 1 from public.supervisor_assignments where room_id=target) then raise exception 'Hapus roster/penugasan terlebih dahulu; riwayat tugas tetap dipertahankan';end if;
 delete from public.exam_rooms where id=target and organization_id=org;result:=jsonb_build_object('saved',found);
 elsif op='session_save' then
 if length(trim(coalesce(input->>'name',''))) not between 1 and 100 or (input->>'starts_at')::timestamptz<ex.starts_at or (input->>'ends_at')::timestamptz>ex.ends_at then raise exception 'Sesi harus di dalam jadwal ujian';end if;
 if target is null then insert into public.exam_sessions(organization_id,exam_id,name,starts_at,ends_at) values(org,eid,input->>'name',(input->>'starts_at')::timestamptz,(input->>'ends_at')::timestamptz) returning id into target;else update public.exam_sessions set name=input->>'name',starts_at=(input->>'starts_at')::timestamptz,ends_at=(input->>'ends_at')::timestamptz where id=target and organization_id=org and exam_id=eid;end if;result:=jsonb_build_object('id',target);
 elsif op='session_delete' then delete from public.exam_sessions where id=target and organization_id=org;result:=jsonb_build_object('saved',found);
 elsif op in ('roster_add','roster_remove') then
 select * into room from public.exam_rooms where id=target and organization_id=org and exam_id=eid for update;if not found then raise exception 'Ruang tidak tersedia';end if;
 if jsonb_array_length(input->'student_ids') not between 1 and 500 then raise exception '1–500 peserta wajib';end if;
 for sid in select distinct value::uuid from jsonb_array_elements_text(input->'student_ids') order by 1 loop
 if exists(select 1 from public.exam_attempts where exam_id=eid and student_id=sid and status<>'reset') then raise exception 'Roster peserta yang sudah mulai dikunci';end if;
 if op='roster_add' then insert into public.exam_room_students values(org,eid,target,sid);else delete from public.exam_room_students where exam_id=eid and room_id=target and student_id=sid;end if;end loop;result:=jsonb_build_object('saved',true);
 elsif op='assign' then
 if input->>'session_id' is null then raise exception 'Sesi tugas wajib';end if;
 insert into public.supervisor_assignments(organization_id,exam_id,room_id,session_id,original_supervisor_id) values(org,eid,(input->>'room_id')::uuid,(input->>'session_id')::uuid,(input->>'supervisor_id')::uuid) returning id into target;result:=jsonb_build_object('id',target);
 elsif op in ('unassign','substitute','revoke') then
 select * into ass from public.supervisor_assignments where id=target and organization_id=org for update;if not found then raise exception 'Tugas tidak tersedia';end if;
 if op='unassign' then update public.supervisor_assignments set active=false where id=target;
 elsif op='revoke' then update public.supervisor_substitutions set revoked_at=clock_timestamp() where assignment_id=target and revoked_at is null;
 else
 if not ass.active or (input->>'supervisor_id')::uuid=ass.original_supervisor_id then raise exception 'Pengganti tidak valid';end if;
 if not exists(select 1 from public.profiles where id=(input->>'supervisor_id')::uuid and organization_id=org and active and role in ('teacher','supervisor')) then raise exception 'Pengganti di luar organisasi';end if;
 update public.supervisor_substitutions set revoked_at=clock_timestamp() where assignment_id=target and revoked_at is null;
 insert into public.supervisor_substitutions(assignment_id,substitute_supervisor_id,effective_from,effective_until) values(target,(input->>'supervisor_id')::uuid,(input->>'starts_at')::timestamptz,(input->>'ends_at')::timestamptz);end if;result:=jsonb_build_object('saved',true);
 elsif op in ('reset','unlock','disqualify') then
 result:='[]';for item in select value from jsonb_array_elements(input->'attempts') order by value->>'id' loop
 select * into a from public.exam_attempts where id=(item->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended(a.student_id::text||a.exam_id::text,0));
 select * into a from public.exam_attempts where id=a.id for update;
 if a.version is distinct from (item->>'version')::int then raise exception 'CONFLICT: Attempt berubah; muat ulang';end if;
 insert into private.attempt_overrides(attempt_id,actor_id,action,reason,before_state) values(a.id,uid,op,input->>'reason',to_jsonb(a));
 if op='reset' then
 if a.status='reset' then raise exception 'Attempt sudah direset';end if;
 update public.exam_attempts set status='reset',writer_epoch=writer_epoch+1,version=version+1,finalized_at=coalesce(finalized_at,clock_timestamp()),review_reason=input->>'reason' where id=a.id;result:=result||jsonb_build_array(jsonb_build_object('id',a.id,'reset',true,'deadline_at',a.deadline_at));
 else result:=result||jsonb_build_array(private.review_attempt(jsonb_build_object('action',op,'attempt_id',a.id,'reason',input->>'reason')));end if;end loop;
 elsif op='broadcast' then
 if length(trim(coalesce(input->>'message',''))) not between 1 and 2000 or input->>'scope' not in ('all','exam','selected') then raise exception 'Pesan/sasaran tidak valid';end if;
 if not public.consume_login_budget('broadcast:'||uid::text) then raise exception 'Batas pengiriman 10 per 15 menit';end if;
 select array_agg(distinct p.id) into ids from public.profiles p where p.organization_id=org and p.active and p.role='student' and ((input->>'scope'='all' and exists(select 1 from public.exams e where private.ops_student(e.id,p.id,false))) or (input->>'scope'='exam' and private.ops_student(eid,p.id,false)) or (input->>'scope'='selected' and p.id in(select value::uuid from jsonb_array_elements_text(input->'student_ids')) and private.ops_student(eid,p.id,false)));
 if coalesce(array_length(ids,1),0)=0 then raise exception 'Tidak ada penerima berizin';end if;
 insert into private.notifications(organization_id,sender_id,message) values(org,uid,trim(input->>'message')) returning id into nid;
 insert into private.notification_receipts select nid,x,null from unnest(ids)x on conflict do nothing;result:=jsonb_build_object('id',nid,'recipients',array_length(ids,1));
 else raise exception 'Aksi operasional tidak dikenal';end if;
 insert into private.operational_requests values(uid,req,input,result);
 insert into public.audit_logs(organization_id,actor_id,action,target_type,target_id,request_id) values(org,uid,'OPS_'||op,'operations',coalesce(target,nid)::text,req);return result;
end$$;
create function public.ops_command(input jsonb) returns jsonb language sql security invoker set search_path='' as $$select private.ops_command(input)$$;
revoke all on function private.effective_supervisor(uuid),private.ops_student(uuid,uuid,boolean),private.reset_attempt_insert(),private.ops_command(jsonb),public.ops_command(jsonb) from public,anon,authenticated;
grant execute on function private.ops_command(jsonb),public.ops_command(jsonb) to authenticated;
-- Broadcast only opaque invalidations. All protected data is fetched again with current authorization.
create function private.ops_signal() returns trigger language plpgsql security definer set search_path='' as $$declare org uuid;begin
 if tg_table_name='notification_receipts' then
 perform realtime.send('{}'::jsonb,'changed','inbox:'||coalesce(new.recipient_id,old.recipient_id)::text,true);
 else
 if tg_table_name in ('attempt_answers','integrity_events') then select organization_id into org from public.exam_attempts where id=coalesce(new.attempt_id,old.attempt_id);
 elsif tg_table_name='supervisor_substitutions' then select organization_id into org from public.supervisor_assignments where id=coalesce(new.assignment_id,old.assignment_id);
 else org:=coalesce(new.organization_id,old.organization_id);end if;
 if org is not null then perform realtime.send('{}'::jsonb,'changed','ops:'||org::text,true);end if;end if;return null;end$$;
revoke all on function private.ops_signal() from public,anon,authenticated;
do $$declare t text;begin foreach t in array array['exam_attempts','attempt_answers','exam_rooms','exam_sessions','exam_room_students','supervisor_assignments','supervisor_substitutions'] loop execute format('create trigger ops_signal after insert or update or delete on public.%I for each row execute function private.ops_signal()',t);end loop;end$$;
create trigger ops_signal after insert on private.integrity_events for each row execute function private.ops_signal();
create trigger inbox_signal after insert on private.notification_receipts for each row execute function private.ops_signal();
create policy ops_channel_receive on realtime.messages for select to authenticated using(private.actor_org() is not null and ((realtime.topic()='inbox:'||auth.uid()::text) or (realtime.topic()='ops:'||private.actor_org()::text and exists(select 1 from public.profiles where id=auth.uid() and active and role in ('admin','teacher','supervisor')))));
-- References must remain valid across current questions, immutable snapshots and pinned report logos.
create function private.media_referenced(mid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.question_versions v where v.payload->'attachments' ? mid::text) or exists(select 1 from private.attempt_questions q where q.student_payload->'attachments' ? mid::text) or exists(select 1 from private.report_settings s where s.logo_media_id=mid) or exists(select 1 from private.export_jobs j where j.settings_snapshot->>'logo_media_id'=mid::text)$$;
create or replace function private.attempt_media_frozen(path text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.media_assets m where m.object_path=path and private.media_referenced(m.id))$$;
create function private.media_command(input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare target uuid:=(input->>'id')::uuid;m public.media_assets;result jsonb;begin
 if not private.is_grader() then raise exception 'AUTH: Akses media diperlukan';end if;
 if input->>'action'='cleanup_list' then select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'path',c.path)),'[]') into result from private.media_cleanup c where c.organization_id=private.actor_org() and not c.done and (private.is_admin() or c.uploader_id=auth.uid());return result;end if;
 if input->>'action' in ('cleanup','cleanup_done') then
 select jsonb_build_object('path',c.path) into result from private.media_cleanup c where c.id=target and c.organization_id=private.actor_org() and not c.done and (private.is_admin() or c.uploader_id=auth.uid()) for update;if not found then raise exception 'AUTH: Pembersihan tidak tersedia';end if;
 if input->>'action'='cleanup_done' then update private.media_cleanup set done=true where id=target;end if;return result;end if;
 if input->>'action'='list' then with filtered as (select m.id,m.object_path,m.mime_type,m.byte_size,m.created_at,private.media_referenced(m.id) referenced from public.media_assets m where m.organization_id=private.actor_org() and (private.is_admin() or m.uploader_id=auth.uid()) and (coalesce(input->>'mime','')='' or m.mime_type like (input->>'mime')||'%')) select jsonb_build_object('total',(select count(*) from filtered),'rows',coalesce(jsonb_agg(to_jsonb(v) order by v.created_at desc),'[]')) into result from(select * from filtered order by created_at desc limit 50 offset (greatest(1,coalesce((input->>'page')::int,1))-1)*50)v;return result;end if;
 select * into m from public.media_assets where id=target and organization_id=private.actor_org() and (private.is_admin() or uploader_id=auth.uid()) for update;if not found then raise exception 'AUTH: Media tidak tersedia';end if;
 if input->>'action'='delete' then if private.media_referenced(target) then raise exception 'Media masih dipakai soal, snapshot atau laporan';end if;delete from public.media_assets where id=target;insert into private.media_cleanup(organization_id,uploader_id,path) values(m.organization_id,m.uploader_id,m.object_path) returning id into target;insert into public.audit_logs(organization_id,actor_id,action,target_type,target_id) values(m.organization_id,auth.uid(),'MEDIA_DELETE','media_assets',m.id::text);return jsonb_build_object('path',m.object_path,'cleanup_id',target);end if;
 raise exception 'Aksi media tidak valid';end$$;
create function public.media_command(input jsonb) returns jsonb language sql security invoker set search_path='' as $$select private.media_command(input)$$;
revoke all on function private.media_referenced(uuid),private.media_command(jsonb),public.media_command(jsonb) from public,anon,authenticated;
grant execute on function private.media_command(jsonb),public.media_command(jsonb) to authenticated;
create function private.pin_job_logo() returns trigger language plpgsql security definer set search_path='' as $$begin
 if nullif(new.settings_snapshot->>'logo_media_id','') is not null then perform 1 from public.media_assets where id=(new.settings_snapshot->>'logo_media_id')::uuid for key share;if not found then raise exception 'Logo tidak tersedia';end if;end if;return new;end$$;
revoke all on function private.pin_job_logo() from public,anon,authenticated;
create trigger pin_job_logo before insert on private.export_jobs for each row execute function private.pin_job_logo();
create table private.card_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null,requested_by uuid not null,request_id uuid not null,input jsonb not null,exam_id uuid not null references public.exams(id),student_ids uuid[] not null,snapshot jsonb not null,format text not null check(format in ('pdf','zip')),status text not null default 'queued' check(status in ('queued','running','ready','failed')),progress int not null default 0,lease uuid,lease_until timestamptz,failures int not null default 0,path text,error text,created_at timestamptz not null default now(),unique(requested_by,request_id));
alter table private.card_jobs enable row level security;revoke all on private.card_jobs from public,anon,authenticated;
create function private.card_access(target uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from private.card_jobs j where j.id=target and j.organization_id=private.actor_org() and j.requested_by=auth.uid() and not exists(select 1 from unnest(j.student_ids) u where not private.ops_student(j.exam_id,u,false)))$$;
create function private.card_object(path text,writing boolean) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from private.card_jobs j where j.id::text=split_part(path,'/',2) and j.requested_by::text=split_part(path,'/',1) and private.card_access(j.id) and (not writing or (j.status='running' and j.lease::text=split_part(path,'/',3) and j.lease_until>clock_timestamp())))$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('exam-cards','exam-cards',false,52428800,array['application/pdf','application/zip']);
create policy cards_read on storage.objects for select to authenticated using(bucket_id='exam-cards' and private.card_object(name,false));
create policy cards_insert on storage.objects for insert to authenticated with check(bucket_id='exam-cards' and private.card_object(name,true));
create function private.card_command(input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare op text:=input->>'action';target uuid:=(input->>'job_id')::uuid;j private.card_jobs;snap jsonb;ids uuid[];result jsonb;begin
 if private.actor_org() is null then raise exception 'AUTH: Sesi tidak valid';end if;
 if op='create' then
 if input->>'template' not in ('compact','large') or input->>'format' not in ('pdf','zip') or jsonb_array_length(input->'student_ids') not between 1 and 500 or (input->>'format'='zip' and jsonb_array_length(input->'student_ids')>50) then raise exception 'PDF 1–500 / ZIP 1–50 peserta; template tidak valid';end if;
 snap:=private.ops_command(jsonb_build_object('action','cards','exam_id',input->>'exam_id','student_ids',input->'student_ids'));
 select array_agg(distinct value::uuid) into ids from jsonb_array_elements_text(input->'student_ids');
 select * into j from private.card_jobs where requested_by=auth.uid() and request_id=(input->>'request_id')::uuid;if found then if j.input<>input then raise exception 'IDEMPOTENCY_CONFLICT';end if;return jsonb_build_object('id',j.id);end if;
 if not public.consume_login_budget('cards:'||auth.uid()::text) then raise exception 'Batas kartu 10 job per 15 menit';end if;
 insert into private.card_jobs(organization_id,requested_by,request_id,input,exam_id,student_ids,snapshot,format) values(private.actor_org(),auth.uid(),(input->>'request_id')::uuid,input,(input->>'exam_id')::uuid,ids,snap,input->>'format') returning * into j;return jsonb_build_object('id',j.id);end if;
 if op='list' then select coalesce(jsonb_agg(jsonb_build_object('id',id,'status',status,'progress',progress,'error',error,'format',format,'created_at',created_at) order by created_at desc),'[]') into result from(select * from private.card_jobs c where private.card_access(c.id) order by created_at desc limit 30)x;return result;end if;
 if not private.card_access(target) then raise exception 'AUTH: Kartu tidak tersedia/izin berubah';end if;
 select * into j from private.card_jobs where id=target for update;
 if op='download' then if j.status<>'ready' then raise exception 'Kartu belum siap';end if;return jsonb_build_object('path',j.path);end if;
 if op='claim' then
 if j.status='ready' then return jsonb_build_object('ready',true);end if;
 if j.status='running' and j.lease_until>clock_timestamp() then return jsonb_build_object('busy',true);end if;
 if j.failures>=5 then raise exception 'Batas retry tercapai';end if;
 update private.card_jobs set status='running',progress=1,lease=gen_random_uuid(),lease_until=clock_timestamp()+interval '4 minutes',error=null where id=target returning * into j;
 return jsonb_build_object('snapshot',j.snapshot,'lease',j.lease,'format',j.format,'template',j.input->>'template','requested_by',j.requested_by);end if;
 if j.status<>'running' or j.lease is distinct from (input->>'lease')::uuid or j.lease_until<clock_timestamp() then raise exception 'CONFLICT: Lease berubah';end if;
 if op='progress' then update private.card_jobs set progress=greatest(progress,least(95,(input->>'progress')::int)),lease_until=clock_timestamp()+interval '4 minutes' where id=target;return '{"saved":true}';end if;
 if op='fail' then update private.card_jobs set status='failed',failures=failures+1,error=left(input->>'message',500) where id=target;return '{"saved":true}';end if;
 if op='finish' then
 if input->>'path' not like j.requested_by::text||'/'||j.id::text||'/'||j.lease::text||'/%.'||j.format or not exists(select 1 from storage.objects where bucket_id='exam-cards' and name=input->>'path' and (metadata->>'size')::bigint between 1 and 52428800) then raise exception 'Artefak/path tidak valid';end if;
 update private.card_jobs set status='ready',progress=100,path=input->>'path' where id=target;return '{"ready":true}';end if;raise exception 'Aksi kartu tidak valid';end$$;
create function public.card_command(input jsonb) returns jsonb language sql security invoker set search_path='' as $$select private.card_command(input)$$;
revoke all on function private.card_access(uuid),private.card_object(text,boolean),private.card_command(jsonb),public.card_command(jsonb) from public,anon,authenticated;
grant execute on function private.card_access(uuid),private.card_object(text,boolean),private.card_command(jsonb),public.card_command(jsonb) to authenticated;

alter table public.media_assets add column sha256 text check(sha256 ~ '^[0-9a-f]{64}$');
create or replace function private.media_referenced(mid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.question_versions v where v.payload->'attachments' ? mid::text) or exists(select 1 from private.attempt_questions q where q.student_payload->'attachments' ? mid::text) or exists(select 1 from private.report_settings s where s.logo_media_id=mid) or exists(select 1 from private.export_jobs j where j.settings_snapshot->>'logo_media_id'=mid::text) or exists(select 1 from private.card_jobs c where c.snapshot->'settings'->>'logo_media_id'=mid::text)$$;
create or replace function private.report_logo_allowed(target uuid) returns boolean language sql stable security definer set search_path='' as $$select private.actor_org() is not null and ((private.is_grader() and (exists(select 1 from private.report_settings s where s.organization_id=private.actor_org() and s.logo_media_id=target) or exists(select 1 from private.export_jobs j where private.job_access(j.id) and j.settings_snapshot->>'logo_media_id'=target::text))) or exists(select 1 from private.card_jobs c where private.card_access(c.id) and c.snapshot->'settings'->>'logo_media_id'=target::text))$$;
create function private.pin_card_logo() returns trigger language plpgsql security definer set search_path='' as $$begin if nullif(new.snapshot->'settings'->>'logo_media_id','') is not null then perform 1 from public.media_assets where id=(new.snapshot->'settings'->>'logo_media_id')::uuid for key share;if not found then raise exception 'Logo tidak tersedia';end if;end if;return new;end$$;
revoke all on function private.pin_card_logo() from public,anon,authenticated;
create trigger pin_card_logo before insert on private.card_jobs for each row execute function private.pin_card_logo();
-- Immutable source bytes: edits create a new asset instead of overwriting a referenced object.
alter policy media_own_insert on storage.objects with check(bucket_id='exam-media' and private.is_grader() and (storage.foldername(name))[1]=auth.uid()::text);
alter policy media_own_update on storage.objects using(false) with check(false);
alter policy media_own_select on storage.objects using(bucket_id='exam-media' and private.actor_org() is not null and ((storage.foldername(name))[1]=auth.uid()::text or (private.is_admin() and exists(select 1 from public.media_assets m where m.object_path=name and m.organization_id=private.actor_org()))));
create table private.media_cleanup(id uuid primary key default gen_random_uuid(),organization_id uuid not null,uploader_id uuid not null,path text not null,done boolean not null default false,created_at timestamptz not null default now());
alter table private.media_cleanup enable row level security;revoke all on private.media_cleanup from public,anon,authenticated;
create function private.source_delete_allowed(path text) returns boolean language sql stable security definer set search_path='' as $$select private.is_grader() and not private.attempt_media_frozen(path) and ((storage.foldername(path))[1]=auth.uid()::text or (private.is_admin() and (exists(select 1 from public.media_assets m where m.object_path=path and m.organization_id=private.actor_org()) or exists(select 1 from private.media_cleanup c where c.path=path and c.organization_id=private.actor_org()))))$$;
revoke all on function private.source_delete_allowed(text) from public,anon;grant execute on function private.source_delete_allowed(text) to authenticated;
alter policy media_own_delete on storage.objects using(bucket_id='exam-media' and private.source_delete_allowed(name));
-- Boolean check is safe for callers; required when evaluated by Storage RLS.
grant execute on function private.is_grader() to authenticated;
